                else if (char == 0x09) output[outputLength++] = "t";
                else if (char == 0x0a) output[outputLength++] = "n";
                else if (char == 0x0c) output[outputLength++] = "f";
                else if (char == 0x0d) output[outputLength++] = "r";
                else if (char == 0x5c) output[outputLength++] = "\\";
                else if (char == 0x22) {
                    // solhint-disable-next-line quotes
                    output[outputLength++] = '"';
                }
            } else {
                output[outputLength++] = char;
            }
        }
        // write the actual length and deallocate unused memory
        assembly ("memory-safe") {
            mstore(output, outputLength)
            mstore(0x40, add(output, shl(5, shr(5, add(outputLength, 63)))))
        }

        return string(output);
    }

    /**
     * @dev Reads a bytes32 from a bytes array without bounds checking.
     *
     * NOTE: making this function internal would mean it could be used with memory unsafe offset, and marking the
     * assembly block as such would prevent some optimizations.
     */
    function _unsafeReadBytesOffset(bytes memory buffer, uint256 offset) private pure returns (bytes32 value) {
        // This is not memory safe in the general case, but all calls to this private function are within bounds.
        assembly ("memory-safe") {
            value := mload(add(add(buffer, 0x20), offset))
        }
    }
}

contracts/ConfidentialERC721.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Royalty.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "fhevm/lib/TFHE.sol";
import "fhevm/gateway/GatewayCaller.sol";

/**
 * @title ConfidentialERC721
 * @notice Privacy-preserving NFT contract using Zama fhEVM v0.9
 * @dev Extends OpenZeppelin ERC721 with encrypted metadata attributes
 */
contract ConfidentialERC721 is ERC721, ERC721Royalty, ReentrancyGuard, Ownable, GatewayCaller {
    using Strings for uint256;

    // Base URI for metadata
    string private _baseTokenURI;

    // Total supply and max supply
    uint256 private _totalSupply;
    uint256 public maxSupply;

    // Next token ID to mint
    uint256 private _nextTokenId;

    // Public minting enabled
    bool public publicMintEnabled;

    // Mint price
    uint256 public mintPrice;

    // Token URIs (tokenId => metadata URI)
    mapping(uint256 => string) private _tokenURIs;

    // Encrypted rarity scores (tokenId => encrypted rarity 0-100)
    mapping(uint256 => euint128) private _encryptedRarity;

    // Encrypted attributes (tokenId => attributeIndex => encrypted value)
    mapping(uint256 => mapping(uint256 => euint128)) private _encryptedAttributes;

    // Number of encrypted attributes per token
    mapping(uint256 => uint256) private _attributeCount;

    // Track if token has encrypted metadata
    mapping(uint256 => bool) public hasEncryptedMetadata;

    // Decryption request tracking (requestId => tokenId)
    mapping(uint256 => uint256) private _decryptionRequests;

    // Events
    event NFTMinted(address indexed to, uint256 indexed tokenId, string uri, bool hasEncrypted);
    event RarityRevealed(uint256 indexed tokenId, uint128 rarity);
    event PublicMintToggled(bool enabled);
    event MintPriceUpdated(uint256 newPrice);

    constructor(
        string memory name_,
        string memory symbol_,
        string memory baseURI_,
        uint256 maxSupply_,
        uint96 royaltyBasisPoints_,
        uint256 mintPrice_
    ) ERC721(name_, symbol_) Ownable(msg.sender) {
        require(maxSupply_ > 0, "Max supply must be positive");
        require(royaltyBasisPoints_ <= 1000, "Royalty too high"); // Max 10%

        _baseTokenURI = baseURI_;
        maxSupply = maxSupply_;
        mintPrice = mintPrice_;
        publicMintEnabled = false;

        // Set default royalty for all tokens
        _setDefaultRoyalty(msg.sender, royaltyBasisPoints_);
    }

    /**
     * @notice Get total supply
     */
    function totalSupply() public view returns (uint256) {
        return _totalSupply;
    }

    /**
     * @notice Toggle public minting (owner only)
     */
    function setPublicMintEnabled(bool enabled) external onlyOwner {
        publicMintEnabled = enabled;
        emit PublicMintToggled(enabled);
    }

    /**
     * @notice Update mint price (owner only)
     */
    function setMintPrice(uint256 newPrice) external onlyOwner {
        mintPrice = newPrice;
        emit MintPriceUpdated(newPrice);
    }

    /**
     * @notice Mint NFT with public metadata only
     */
    function mint(string memory tokenURI_) public payable nonReentrant returns (uint256) {
        if (!publicMintEnabled) {
            require(msg.sender == owner(), "Public mint disabled");
        }
        require(msg.value >= mintPrice, "Insufficient payment");
        require(_totalSupply < maxSupply, "Max supply reached");

        uint256 tokenId = _nextTokenId++;
        _totalSupply++;

        _safeMint(msg.sender, tokenId);
        _tokenURIs[tokenId] = tokenURI_;

        // Refund excess payment using safe call
        if (msg.value > mintPrice) {
            (bool success,) = payable(msg.sender).call{value: msg.value - mintPrice}("");
            require(success, "Refund failed");
        }

        emit NFTMinted(msg.sender, tokenId, tokenURI_, false);
        return tokenId;
    }

    /**
     * @notice Mint NFT with encrypted rarity
     */
    function mintWithEncryptedRarity(
        string memory tokenURI_,
        einput encryptedRarity_,
        bytes calldata rarityProof_
    ) public payable nonReentrant returns (uint256) {
        if (!publicMintEnabled) {
            require(msg.sender == owner(), "Public mint disabled");
        }
        require(msg.value >= mintPrice, "Insufficient payment");
        require(_totalSupply < maxSupply, "Max supply reached");

        uint256 tokenId = _nextTokenId++;
        _totalSupply++;

        _safeMint(msg.sender, tokenId);
        _tokenURIs[tokenId] = tokenURI_;

        // Store encrypted rarity
        euint128 rarityValue = TFHE.asEuint128(encryptedRarity_, rarityProof_);
        _encryptedRarity[tokenId] = rarityValue;
        TFHE.allow(rarityValue, msg.sender);
        TFHE.allowThis(rarityValue);
        hasEncryptedMetadata[tokenId] = true;

        // Refund excess payment using safe call
        if (msg.value > mintPrice) {
            (bool success,) = payable(msg.sender).call{value: msg.value - mintPrice}("");
            require(success, "Refund failed");
        }

        emit NFTMinted(msg.sender, tokenId, tokenURI_, true);
        return tokenId;
    }

    /**
     * @notice Mint NFT with encrypted attributes (owner or authorized)
     */
    function mintWithEncryptedAttributes(
        address to,
        string memory tokenURI_,
        einput encryptedRarity_,
        bytes calldata rarityProof_,
        einput[] calldata encryptedAttrs_,
        bytes[] calldata attrProofs_
    ) public onlyOwner nonReentrant returns (uint256) {
        require(to != address(0), "Invalid recipient");
        require(_totalSupply < maxSupply, "Max supply reached");
        require(encryptedAttrs_.length == attrProofs_.length, "Mismatched arrays");
        require(encryptedAttrs_.length <= 10, "Too many attributes");

        uint256 tokenId = _nextTokenId++;
        _totalSupply++;

        _safeMint(to, tokenId);
        _tokenURIs[tokenId] = tokenURI_;

        // Store encrypted rarity
        euint128 rarityValue = TFHE.asEuint128(encryptedRarity_, rarityProof_);
        _encryptedRarity[tokenId] = rarityValue;
        TFHE.allow(rarityValue, to);
        TFHE.allowThis(rarityValue);

        // Store encrypted attributes
        for (uint256 i = 0; i < encryptedAttrs_.length; i++) {
            euint128 attrValue = TFHE.asEuint128(encryptedAttrs_[i], attrProofs_[i]);
            _encryptedAttributes[tokenId][i] = attrValue;
            TFHE.allow(attrValue, to);
            TFHE.allowThis(attrValue);
        }
        _attributeCount[tokenId] = encryptedAttrs_.length;
        hasEncryptedMetadata[tokenId] = true;

        emit NFTMinted(to, tokenId, tokenURI_, true);
        return tokenId;
    }

    /**
     * @notice Batch mint (owner only)
     */
    function batchMint(address to, uint256 quantity, string memory baseTokenURI_) 
        external 
        onlyOwner 
        nonReentrant 
    {
        require(to != address(0), "Invalid recipient");
        require(quantity > 0 && quantity <= 100, "Invalid quantity");
        require(_totalSupply + quantity <= maxSupply, "Exceeds max supply");

        for (uint256 i = 0; i < quantity; i++) {
            uint256 tokenId = _nextTokenId++;
            _totalSupply++;

            _safeMint(to, tokenId);
            _tokenURIs[tokenId] = string(abi.encodePacked(baseTokenURI_, tokenId.toString()));

            emit NFTMinted(to, tokenId, _tokenURIs[tokenId], false);
        }
    }

    /**
     * @notice Override transfer to update encrypted data permissions
     */
    function _update(address to, uint256 tokenId, address auth)
        internal
        override
        returns (address)
    {
        address from = super._update(to, tokenId, auth);

        // Update encrypted data permissions on transfer
        if (to != address(0) && hasEncryptedMetadata[tokenId]) {
            TFHE.allow(_encryptedRarity[tokenId], to);

            // Update all attribute permissions
            for (uint256 i = 0; i < _attributeCount[tokenId]; i++) {
                TFHE.allow(_encryptedAttributes[tokenId][i], to);
            }
        }

        return from;
    }

    /**
     * @notice Burn NFT
     */
    function burn(uint256 tokenId) public {
        require(ownerOf(tokenId) == msg.sender, "Not token owner");

        _totalSupply--;

        // Clean up encrypted data
        if (hasEncryptedMetadata[tokenId]) {
            // Note: Cannot delete euint128 types - they remain in storage
            // delete _encryptedRarity[tokenId]; // fhEVM types cannot be deleted
            uint256 attrCount = _attributeCount[tokenId];
            // for (uint256 i = 0; i < attrCount; i++) {
            //     delete _encryptedAttributes[tokenId][i]; // fhEVM types cannot be deleted
            // }
            delete _attributeCount[tokenId];
            delete hasEncryptedMetadata[tokenId];
        }

        delete _tokenURIs[tokenId];
        _burn(tokenId);
    }

    /**
     * @notice Get token URI
     */
    function tokenURI(uint256 tokenId) 
        public 
        view 
        override 
        returns (string memory) 
    {
        _requireOwned(tokenId);

        string memory _tokenURI = _tokenURIs[tokenId];

        // If custom URI exists, return it
        if (bytes(_tokenURI).length > 0) {
            return _tokenURI;
        }

        // Otherwise return base URI + tokenId
        string memory base = _baseURI();
        return bytes(base).length > 0 
            ? string(abi.encodePacked(base, tokenId.toString())) 
            : "";
    }

    /**
     * @notice Get base URI
     */
    function _baseURI() internal view override returns (string memory) {
        return _baseTokenURI;
    }

    /**
     * @notice Update base URI (owner only)
     */
    function setBaseURI(string memory newBaseURI) external onlyOwner {
        _baseTokenURI = newBaseURI;
    }

    /**
     * @notice Get encrypted rarity
     */
    function getEncryptedRarity(uint256 tokenId) public view returns (euint128) {
        require(hasEncryptedMetadata[tokenId], "No encrypted metadata");
        return _encryptedRarity[tokenId];
    }

    /**
     * @notice Get encrypted attribute
     */
    function getEncryptedAttribute(uint256 tokenId, uint256 attributeIndex) 
        public 
        view 
        returns (euint128) 
    {
        require(hasEncryptedMetadata[tokenId], "No encrypted metadata");
        require(attributeIndex < _attributeCount[tokenId], "Invalid attribute index");
        return _encryptedAttributes[tokenId][attributeIndex];
    }

    /**
     * @notice Get attribute count
     */
    function getAttributeCount(uint256 tokenId) public view returns (uint256) {
        return _attributeCount[tokenId];
    }

    /**
     * @notice Request rarity decryption (owner only)
     */
    function requestRarityDecryption(uint256 tokenId) public returns (uint256) {
        require(ownerOf(tokenId) == msg.sender, "Not token owner");
        require(hasEncryptedMetadata[tokenId], "No encrypted metadata");

        uint256[] memory cts = new uint256[](1);
        cts[0] = Gateway.toUint256(_encryptedRarity[tokenId]);

        uint256 requestId = Gateway.requestDecryption(
            cts,
            this.callbackRarityDecryption.selector,
            0,
            block.timestamp + 100,
            false
        );

        _decryptionRequests[requestId] = tokenId;
        return requestId;
    }

    /**
     * @notice Callback for rarity decryption
     */
    function callbackRarityDecryption(
        uint256 requestId,
        uint128 decryptedRarity
    ) public onlyGateway {
        uint256 tokenId = _decryptionRequests[requestId];
        delete _decryptionRequests[requestId];

        emit RarityRevealed(tokenId, decryptedRarity);
    }

    /**
     * @notice Withdraw contract balance (owner only)
     */
    function withdraw() external onlyOwner nonReentrant {
        uint256 balance = address(this).balance;
        require(balance > 0, "No balance");
        (bool success,) = payable(owner()).call{value: balance}("");
        require(success, "Withdrawal failed");
    }

    /**
     * @notice Override supportsInterface for ERC721Royalty
     */
    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, ERC721Royalty)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

contracts/ConfidentialMarketplace.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "fhevm/lib/TFHE.sol";
import "fhevm/gateway/GatewayCaller.sol";

interface IERC721WithRoyalty is IERC721 {
    function royaltyInfo(uint256 tokenId, uint256 salePrice) 
        external 
        view 
        returns (address receiver, uint256 royaltyAmount);
}

/**
 * @title ConfidentialMarketplace
 * @notice Privacy-preserving NFT marketplace using Zama fhEVM v0.9
 * @dev Implements secure escrow, reentrancy protection, and encrypted pricing
 */
contract ConfidentialMarketplace is ReentrancyGuard, Ownable, GatewayCaller {
    // Payout structure
    struct Payout {
        uint256 platformFee;
        uint256 royaltyAmount;
        address royaltyRecipient;
        uint256 sellerProceeds;
    }

    // Platform fee (basis points, e.g., 250 = 2.5%)
    uint256 public platformFeeBasisPoints;
    address public feeRecipient;

    // Listing structure
    struct Listing {
        address nftContract;
        uint256 tokenId;
        address seller;
        uint256 price;
        bool isActive;
        uint256 createdAt;
    }

    // Offer structure
    struct Offer {
        address nftContract;
        uint256 tokenId;
        address bidder;
        uint256 amount;
        bool isActive;
        uint256 createdAt;
        uint256 expiresAt;
    }

    // Auction structure
    struct Auction {
        address nftContract;
        uint256 tokenId;
        address seller;
        uint256 reservePrice;
        uint256 highestBid;
        address highestBidder;
        uint256 startTime;
        uint256 endTime;
        bool isActive;
        bool isFinalized;
    }

    // Storage
    mapping(uint256 => Listing) public listings;
    uint256 public listingCount;

    mapping(uint256 => Offer) public offers;
    uint256 public offerCount;

    mapping(uint256 => Auction) public auctions;
    uint256 public auctionCount;

    // Track escrowed NFTs (nftContract => tokenId => escrowId)
    mapping(address => mapping(uint256 => uint256)) private _escrowedNFTs;

    // Events
    event NFTListed(
        uint256 indexed listingId,
        address indexed nftContract,
        uint256 indexed tokenId,
        address seller,
        uint256 price
    );
    event NFTSold(
        uint256 indexed listingId,
        address indexed buyer,
        address indexed seller,
        uint256 price
    );
    event ListingCancelled(uint256 indexed listingId);
    event OfferMade(
        uint256 indexed offerId,
        address indexed nftContract,
        uint256 indexed tokenId,
        address bidder,
        uint256 amount
    );
    event OfferAccepted(uint256 indexed offerId, address seller);
    event OfferCancelled(uint256 indexed offerId);
    event AuctionCreated(
        uint256 indexed auctionId,
        address indexed nftContract,
        uint256 indexed tokenId,
        uint256 reservePrice,
        uint256 endTime
    );
    event BidPlaced(
        uint256 indexed auctionId,
        address indexed bidder,
        uint256 amount
    );
    event AuctionFinalized(
        uint256 indexed auctionId,
        address winner,
        uint256 finalPrice
    );
    event PlatformFeeUpdated(uint256 newFee);
    event FeeRecipientUpdated(address newRecipient);

    constructor(uint256 platformFeeBasisPoints_) Ownable(msg.sender) {
        require(platformFeeBasisPoints_ <= 1000, "Fee too high"); // Max 10%
        platformFeeBasisPoints = platformFeeBasisPoints_;
        feeRecipient = msg.sender;
    }

    /**
     * @notice Calculate payout with validation
     * @dev Internal function to prevent fund trapping
     */
    function _calculatePayout(
        uint256 price,
        address nftContract,
        uint256 tokenId
    ) private view returns (Payout memory) {
        // Calculate platform fee
        uint256 platformFee = (price * platformFeeBasisPoints) / 10000;
        require(price >= platformFee, "Price too low for fees");
        require(feeRecipient != address(0), "Invalid fee recipient");

        uint256 royaltyAmount = 0;
        address royaltyRecipient = address(0);

        // Try to get royalty info (EIP-2981)
        try IERC721WithRoyalty(nftContract).royaltyInfo(tokenId, price) 
            returns (address recipient, uint256 amount) 
        {
            royaltyAmount = amount;
            royaltyRecipient = recipient;

            // Validate royalty recipient if amount > 0
            if (royaltyAmount > 0) {
                require(royaltyRecipient != address(0), "Invalid royalty recipient");
            }

            // Cap royalty + fee to prevent underflow
            if (platformFee + royaltyAmount > price) {
                royaltyAmount = price > platformFee ? price - platformFee : 0;
            }
        } catch {
            // No royalty support - proceed with zero royalty
        }

        // Calculate seller proceeds with invariant check
        uint256 sellerProceeds = price - platformFee - royaltyAmount;

        // Verify balance conservation
        assert(platformFee + royaltyAmount + sellerProceeds == price);

        // Ensure royalty consistency: if recipient is zero, amount must be zero
        require(
            (royaltyRecipient != address(0)) || (royaltyAmount == 0),
            "Royalty recipient required for non-zero amount"
        );

        return Payout({
            platformFee: platformFee,
            royaltyAmount: royaltyAmount,
            royaltyRecipient: royaltyRecipient,
            sellerProceeds: sellerProceeds
        });
    }

    /**
     * @notice Execute payout transfers
     * @dev Internal function to distribute funds safely
     */
    function _executePayout(Payout memory payout, address seller) private {
        // Transfer platform fee
        if (payout.platformFee > 0) {
            (bool feeSuccess,) = feeRecipient.call{value: payout.platformFee}("");
            require(feeSuccess, "Fee transfer failed");
        }

        // Transfer royalty
        if (payout.royaltyAmount > 0) {
            (bool royaltySuccess,) = payout.royaltyRecipient.call{value: payout.royaltyAmount}("");
            require(royaltySuccess, "Royalty transfer failed");
        }

        // Transfer to seller
        if (payout.sellerProceeds > 0) {
            (bool sellerSuccess,) = seller.call{value: payout.sellerProceeds}("");
            require(sellerSuccess, "Seller payment failed");
        }
    }

    /**
     * @notice List NFT for sale with escrow
     */
    function listNFT(
        address nftContract,
        uint256 tokenId,
        uint256 price
    ) external nonReentrant returns (uint256) {
        require(price > 0, "Invalid price");
        require(_escrowedNFTs[nftContract][tokenId] == 0, "NFT already escrowed");

        IERC721 nft = IERC721(nftContract);
        require(nft.ownerOf(tokenId) == msg.sender, "Not token owner");
        require(
            nft.isApprovedForAll(msg.sender, address(this)) || 
            nft.getApproved(tokenId) == address(this),
            "Marketplace not approved"
        );

        uint256 listingId = listingCount++;

        // Escrow NFT
        nft.transferFrom(msg.sender, address(this), tokenId);
        _escrowedNFTs[nftContract][tokenId] = listingId + 1; // +1 to differentiate from 0

        listings[listingId] = Listing({
            nftContract: nftContract,
            tokenId: tokenId,
            seller: msg.sender,
            price: price,
            isActive: true,
            createdAt: block.timestamp
        });

        emit NFTListed(listingId, nftContract, tokenId, msg.sender, price);
        return listingId;
    }

    /**
     * @notice Buy NFT from listing
     */
    function buyNFT(uint256 listingId) external payable nonReentrant {
        Listing storage listing = listings[listingId];
        require(listing.isActive, "Listing not active");
        require(msg.value >= listing.price, "Insufficient payment");
        require(msg.sender != listing.seller, "Cannot buy own NFT");

        listing.isActive = false;
        _escrowedNFTs[listing.nftContract][listing.tokenId] = 0;

        // Calculate payout with validation
        Payout memory payout = _calculatePayout(
            listing.price,
            listing.nftContract,
            listing.tokenId
        );

        // Transfer NFT to buyer
        IERC721(listing.nftContract).transferFrom(address(this), msg.sender, listing.tokenId);

        // Execute payout transfers
        _executePayout(payout, listing.seller);

        // Refund excess
        if (msg.value > listing.price) {
            (bool refundSuccess,) = msg.sender.call{value: msg.value - listing.price}("");
            require(refundSuccess, "Refund failed");
        }

        emit NFTSold(listingId, msg.sender, listing.seller, listing.price);
    }

    /**
     * @notice Cancel listing and return NFT
     */
    function cancelListing(uint256 listingId) external nonReentrant {
        Listing storage listing = listings[listingId];
        require(listing.seller == msg.sender, "Not seller");
        require(listing.isActive, "Listing not active");

        listing.isActive = false;
        _escrowedNFTs[listing.nftContract][listing.tokenId] = 0;

        // Return NFT to seller
        IERC721(listing.nftContract).transferFrom(
            address(this),
            listing.seller,
            listing.tokenId
        );

        emit ListingCancelled(listingId);
    }

    /**
     * @notice Make offer on NFT (escrows ETH)
     */
    function makeOffer(
        address nftContract,
        uint256 tokenId,
        uint256 duration
    ) external payable nonReentrant returns (uint256) {
        require(msg.value > 0, "Offer must have value");
        require(duration > 0 && duration <= 30 days, "Invalid duration");

        IERC721 nft = IERC721(nftContract);
        require(nft.ownerOf(tokenId) != address(0), "Token does not exist");

        uint256 offerId = offerCount++;
        uint256 expiresAt = block.timestamp + duration;

        offers[offerId] = Offer({
            nftContract: nftContract,
            tokenId: tokenId,
            bidder: msg.sender,
            amount: msg.value,
            isActive: true,
            createdAt: block.timestamp,
            expiresAt: expiresAt
        });

        emit OfferMade(offerId, nftContract, tokenId, msg.sender, msg.value);
        return offerId;
    }

    /**
     * @notice Accept offer (NFT owner only)
     */
    function acceptOffer(uint256 offerId) external nonReentrant {
        Offer storage offer = offers[offerId];
        require(offer.isActive, "Offer not active");
        require(block.timestamp < offer.expiresAt, "Offer expired");

        IERC721 nft = IERC721(offer.nftContract);
        require(nft.ownerOf(offer.tokenId) == msg.sender, "Not token owner");
        require(
            nft.isApprovedForAll(msg.sender, address(this)) || 
            nft.getApproved(offer.tokenId) == address(this),
            "Marketplace not approved"
        );

        offer.isActive = false;

        // Calculate payout with validation
        Payout memory payout = _calculatePayout(
            offer.amount,
            offer.nftContract,
            offer.tokenId
        );

        // Transfer NFT to bidder
        nft.transferFrom(msg.sender, offer.bidder, offer.tokenId);

        // Execute payout transfers
        _executePayout(payout, msg.sender);

        emit OfferAccepted(offerId, msg.sender);
    }

    /**
     * @notice Cancel offer and refund
     */
    function cancelOffer(uint256 offerId) external nonReentrant {
        Offer storage offer = offers[offerId];
        require(offer.bidder == msg.sender, "Not bidder");
        require(offer.isActive, "Offer not active");

        uint256 refundAmount = offer.amount;
        offer.isActive = false;
        offer.amount = 0; // Clear amount before refund

        // Refund bidder with validated result
        if (refundAmount > 0) {
            (bool success,) = offer.bidder.call{value: refundAmount}("");
            require(success, "Refund failed");
        }

        emit OfferCancelled(offerId);
    }

    /**
     * @notice Create auction (escrows NFT)
     */
    function createAuction(
        address nftContract,
        uint256 tokenId,
        uint256 reservePrice,
        uint256 duration
    ) external nonReentrant returns (uint256) {
        require(reservePrice > 0, "Invalid reserve price");
        require(duration >= 1 hours && duration <= 30 days, "Invalid duration");
        require(_escrowedNFTs[nftContract][tokenId] == 0, "NFT already escrowed");

        IERC721 nft = IERC721(nftContract);
        require(nft.ownerOf(tokenId) == msg.sender, "Not token owner");
        require(
            nft.isApprovedForAll(msg.sender, address(this)) || 
            nft.getApproved(tokenId) == address(this),
            "Marketplace not approved"
        );

        uint256 auctionId = auctionCount++;
        uint256 endTime = block.timestamp + duration;

        // Escrow NFT
        nft.transferFrom(msg.sender, address(this), tokenId);
        _escrowedNFTs[nftContract][tokenId] = auctionId + 1;

        auctions[auctionId] = Auction({
            nftContract: nftContract,
            tokenId: tokenId,
            seller: msg.sender,
            reservePrice: reservePrice,
            highestBid: 0,
            highestBidder: address(0),
            startTime: block.timestamp,
            endTime: endTime,
            isActive: true,
            isFinalized: false
        });

        emit AuctionCreated(auctionId, nftContract, tokenId, reservePrice, endTime);
        return auctionId;
    }

    /**
     * @notice Place bid on auction (escrows ETH)
     */
    function placeBid(uint256 auctionId) external payable nonReentrant {
        Auction storage auction = auctions[auctionId];
        require(auction.isActive, "Auction not active");
        require(block.timestamp < auction.endTime, "Auction ended");
        require(msg.sender != auction.seller, "Seller cannot bid");
        require(msg.value >= auction.reservePrice, "Below reserve price");
        require(msg.value > auction.highestBid, "Bid too low");

        // Refund previous highest bidder with validated result
        if (auction.highestBidder != address(0) && auction.highestBid > 0) {
            address previousBidder = auction.highestBidder;
            uint256 previousBid = auction.highestBid;

            // Update state before refund
            auction.highestBid = 0;
            auction.highestBidder = address(0);

            (bool success,) = previousBidder.call{value: previousBid}("");
            require(success, "Previous bidder refund failed");
        }

        auction.highestBid = msg.value;
        auction.highestBidder = msg.sender;

        emit BidPlaced(auctionId, msg.sender, msg.value);
    }

    /**
     * @notice Finalize auction after end time
     */
    function finalizeAuction(uint256 auctionId) external nonReentrant {
        Auction storage auction = auctions[auctionId];
        require(auction.isActive, "Auction not active");
        require(block.timestamp >= auction.endTime, "Auction still ongoing");
        require(!auction.isFinalized, "Already finalized");

        auction.isActive = false;
        auction.isFinalized = true;
        _escrowedNFTs[auction.nftContract][auction.tokenId] = 0;

        if (auction.highestBidder != address(0) && auction.highestBid >= auction.reservePrice) {
            // Auction successful - calculate payout with validation
            Payout memory payout = _calculatePayout(
                auction.highestBid,
                auction.nftContract,
                auction.tokenId
            );

            // Transfer NFT to winner
            IERC721(auction.nftContract).transferFrom(
                address(this),
                auction.highestBidder,
                auction.tokenId
            );

            // Execute payout transfers
            _executePayout(payout, auction.seller);

            emit AuctionFinalized(auctionId, auction.highestBidder, auction.highestBid);
        } else {
            // Auction failed (no bids or below reserve), return NFT to seller
            IERC721(auction.nftContract).transferFrom(
                address(this),
                auction.seller,
                auction.tokenId
            );

            // Refund highest bidder if below reserve with validated result
            if (auction.highestBidder != address(0) && auction.highestBid > 0) {
                address bidderToRefund = auction.highestBidder;
                uint256 amountToRefund = auction.highestBid;

                // Clear state before refund
                auction.highestBid = 0;
                auction.highestBidder = address(0);

                (bool success,) = bidderToRefund.call{value: amountToRefund}("");
                require(success, "Bidder refund failed");
            }

            emit AuctionFinalized(auctionId, address(0), 0);
        }
    }

    /**
     * @notice Update platform fee (owner only)
     */
    function setPlatformFee(uint256 newFeeBasisPoints) external onlyOwner {
        require(newFeeBasisPoints <= 1000, "Fee too high");
        platformFeeBasisPoints = newFeeBasisPoints;
        emit PlatformFeeUpdated(newFeeBasisPoints);
    }

    /**
     * @notice Update fee recipient (owner only)
     */
    function setFeeRecipient(address newRecipient) external onlyOwner {
        require(newRecipient != address(0), "Invalid recipient");
        feeRecipient = newRecipient;
        emit FeeRecipientUpdated(newRecipient);
    }

    /**
     * @notice Get listing details
     */
    function getListing(uint256 listingId) external view returns (
        address nftContract,
        uint256 tokenId,
        address seller,
        uint256 price,
        bool isActive,
        uint256 createdAt
    ) {
        Listing memory listing = listings[listingId];
        return (
            listing.nftContract,
            listing.tokenId,
            listing.seller,
            listing.price,
            listing.isActive,
            listing.createdAt
        );
    }

    /**
     * @notice Get auction details
     */
    function getAuction(uint256 auctionId) external view returns (
        address nftContract,
        uint256 tokenId,
        address seller,
        uint256 reservePrice,
        uint256 highestBid,
        address highestBidder,
        uint256 endTime,
        bool isActive,
        bool isFinalized
    ) {
        Auction memory auction = auctions[auctionId];
        return (
            auction.nftContract,
            auction.tokenId,
            auction.seller,
            auction.reservePrice,
            auction.highestBid,
            auction.highestBidder,
            auction.endTime,
            auction.isActive,
            auction.isFinalized
        );
    }

    /**
     * @notice Check if NFT is escrowed
     */
    function isEscrowed(address nftContract, uint256 tokenId) external view returns (bool) {
        return _escrowedNFTs[nftContract][tokenId] != 0;
    }
}

contracts/ConfidentialPresale.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "fhevm/lib/TFHE.sol";
import "fhevm/gateway/GatewayCaller.sol";

interface IConfidentialToken {
    function transfer(address to, einput amount, bytes calldata inputProof) external returns (bool);
    function balanceOf(address account) external view returns (euint128);
}

/**
 * @title ConfidentialPresale
 * @notice Privacy-preserving presale contract using Zama fhEVM v0.9
 * @dev Supports encrypted contributions for maximum privacy
 */
contract ConfidentialPresale is GatewayCaller {
    // Presale parameters
    address public tokenAddress;
    address public owner;
    uint256 public rate; // Tokens per ETH (with decimals)
    uint256 public hardCap; // Maximum ETH to raise
    uint256 public softCap; // Minimum ETH to raise
    uint256 public minContribution; // Minimum contribution per address
    uint256 public maxContribution; // Maximum contribution per address
    uint256 public startTime;
    uint256 public endTime;
    bool public isEncrypted;

    // Presale state
    uint256 public totalRaised;
    uint256 public totalContributors;
    bool public finalized;
    bool public softCapReached;

    // Encrypted contributions mapping - using euint128 for larger values
    mapping(address => euint128) private _encryptedContributions;

    // Public contributions (when not encrypted)
    mapping(address => uint256) public contributions;

    // Has claimed tokens
    mapping(address => bool) public hasClaimed;

    // Events
    event Contribution(address indexed contributor, bool encrypted);
    event TokensClaimed(address indexed contributor, uint256 amount);
    event PresaleFinalized(bool success, uint256 totalRaised);
    event RefundClaimed(address indexed contributor, uint256 amount);

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner");
        _;
    }

    modifier whileActive() {
        require(block.timestamp >= startTime, "Presale not started");
        require(block.timestamp <= endTime, "Presale ended");
        require(!finalized, "Presale finalized");
        require(totalRaised < hardCap, "Hard cap reached");
        _;
    }

    constructor(
        address _tokenAddress,
        uint256 _rate,
        uint256 _hardCap,
        uint256 _softCap,
        uint256 _minContribution,
        uint256 _maxContribution,
        uint256 _startTime,
        uint256 _endTime,
        bool _isEncrypted
    ) {
        require(_tokenAddress != address(0), "Invalid token address");
        require(_rate > 0, "Rate must be positive");
        require(_hardCap > _softCap, "Hard cap must exceed soft cap");
        require(_maxContribution >= _minContribution, "Invalid contribution limits");
        require(_endTime > _startTime, "Invalid time range");

        tokenAddress = _tokenAddress;
        owner = msg.sender;
        rate = _rate;
        hardCap = _hardCap;
        softCap = _softCap;
        minContribution = _minContribution;
        maxContribution = _maxContribution;
        startTime = _startTime;
        endTime = _endTime;
        isEncrypted = _isEncrypted;
    }

    /**
     * @notice Contribute ETH to presale
     */
    function contribute() external payable whileActive {
        require(msg.value >= minContribution, "Below minimum contribution");
        require(msg.value <= maxContribution, "Exceeds maximum contribution");
        require(totalRaised + msg.value <= hardCap, "Exceeds hard cap");

        if (contributions[msg.sender] == 0 && !isEncrypted) {
            totalContributors++;
        }

        if (isEncrypted) {
            // Store encrypted contribution using euint128
            euint128 newContribution = TFHE.asEuint128(msg.value);

            if (TFHE.isInitialized(_encryptedContributions[msg.sender])) {
                _encryptedContributions[msg.sender] = TFHE.add(
                    _encryptedContributions[msg.sender],
                    newContribution
                );
            } else {
                _encryptedContributions[msg.sender] = newContribution;
                totalContributors++;
            }

            TFHE.allow(_encryptedContributions[msg.sender], msg.sender);
            TFHE.allowThis(_encryptedContributions[msg.sender]);
        } else {
            // Store public contribution
            contributions[msg.sender] += msg.value;
        }

        totalRaised += msg.value;

        if (totalRaised >= softCap) {
            softCapReached = true;
        }

        emit Contribution(msg.sender, isEncrypted);
    }

    /**
     * @notice Contribute with encrypted amount
     */
    function contributeEncrypted(einput amount, bytes calldata inputProof) external payable whileActive {
        require(isEncrypted, "Presale does not use encryption");
        require(msg.value >= minContribution, "Below minimum contribution");
        require(msg.value <= maxContribution, "Exceeds maximum contribution");
        require(totalRaised + msg.value <= hardCap, "Exceeds hard cap");

        euint128 encryptedAmount = TFHE.asEuint128(amount, inputProof);

        if (TFHE.isInitialized(_encryptedContributions[msg.sender])) {
            _encryptedContributions[msg.sender] = TFHE.add(
                _encryptedContributions[msg.sender],
                encryptedAmount
            );
        } else {
            _encryptedContributions[msg.sender] = encryptedAmount;
            totalContributors++;
        }

        TFHE.allow(_encryptedContributions[msg.sender], msg.sender);
        TFHE.allowThis(_encryptedContributions[msg.sender]);

        totalRaised += msg.value;

        if (totalRaised >= softCap) {
            softCapReached = true;
        }

        emit Contribution(msg.sender, true);
    }

    /**
     * @notice Finalize presale (owner only)
     */
    function finalize() external onlyOwner {
        require(block.timestamp > endTime || totalRaised >= hardCap, "Cannot finalize yet");
        require(!finalized, "Already finalized");

        finalized = true;

        if (totalRaised >= softCap) {
            // Transfer raised funds to owner
            payable(owner).transfer(totalRaised);
            emit PresaleFinalized(true, totalRaised);
        } else {
            emit PresaleFinalized(false, totalRaised);
        }
    }

    /**
     * @notice Claim tokens after successful presale
     */
    function claimTokens() external {
        require(finalized, "Presale not finalized");
        require(totalRaised >= softCap, "Soft cap not reached");
        require(!hasClaimed[msg.sender], "Already claimed");

        uint256 contributionAmount;

        if (isEncrypted) {
            // For encrypted contributions, we'd need a decryption flow
            // For now, this is a simplified version
            revert("Use claimTokensWithDecryption for encrypted presales");
        } else {
            contributionAmount = contributions[msg.sender];
        }

        require(contributionAmount > 0, "No contribution found");

        uint256 tokenAmount = (contributionAmount * rate) / 1e18;
        hasClaimed[msg.sender] = true;

        // Transfer tokens to contributor
        // Note: This requires the presale contract to have been approved tokens
        // In production, implement proper token transfer logic

        emit TokensClaimed(msg.sender, tokenAmount);
    }

    /**
     * @notice Claim refund if soft cap not reached
     */
    function claimRefund() external {
        require(finalized, "Presale not finalized");
        require(totalRaised < softCap, "Soft cap was reached");
        require(!hasClaimed[msg.sender], "Already claimed");

        uint256 refundAmount;

        if (isEncrypted) {
            revert("Use claimRefundWithDecryption for encrypted presales");
        } else {
            refundAmount = contributions[msg.sender];
        }

        require(refundAmount > 0, "No contribution to refund");

        hasClaimed[msg.sender] = true;
        contributions[msg.sender] = 0;

        payable(msg.sender).transfer(refundAmount);
        emit RefundClaimed(msg.sender, refundAmount);
    }

    /**
     * @notice Get encrypted contribution for an address
     */
    function getEncryptedContribution(address contributor) public view returns (euint128) {
        require(isEncrypted, "Presale does not use encryption");
        return _encryptedContributions[contributor];
    }

    /**
     * @notice Check if presale is active
     */
    function isActive() public view returns (bool) {
        return block.timestamp >= startTime &&
               block.timestamp <= endTime &&
               !finalized &&
               totalRaised < hardCap;
    }

    /**
     * @notice Get presale info
     */
    function getPresaleInfo() external view returns (
        uint256 _totalRaised,
        uint256 _totalContributors,
        bool _isActive,
        bool _softCapReached,
        bool _finalized
    ) {
        return (
            totalRaised,
            totalContributors,
            isActive(),
            softCapReached,
            finalized
        );
    }
}

contracts/ConfidentialToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "fhevm/lib/TFHE.sol";
import "fhevm/gateway/GatewayCaller.sol";

/**
 * @title ConfidentialToken
 * @notice Privacy-preserving ERC20 token using Zama fhEVM v0.9
 * @dev Implements encrypted balances and optional encrypted total supply using euint128 for standard ERC20 compatibility
 */
contract ConfidentialToken is GatewayCaller {
    // Token metadata
    string public name;
    string public symbol;
    uint8 public decimals;

    // Encrypted total supply (optional) - using euint128 to support 18 decimal tokens
    euint128 private _encryptedTotalSupply;
    bool public isSupplyEncrypted;

    // Public total supply (when not encrypted)
    uint256 public totalSupply;

    // Encrypted balances for each address - using euint128 for full ERC20 range
    mapping(address => euint128) private _encryptedBalances;

    // Encrypted allowances: owner => spender => amount
    mapping(address => mapping(address => euint128)) private _encryptedAllowances;

    // Owner of the contract
    address public owner;

    // Events
    event Transfer(address indexed from, address indexed to);
    event Approval(address indexed owner, address indexed spender);
    event TotalSupplyRevealed(uint256 amount);

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this");
        _;
    }

    /**
     * @notice Constructor to create a new confidential token
     * @param _name Token name
     * @param _symbol Token symbol
     * @param _decimals Number of decimals
     * @param _totalSupply Initial total supply
     * @param _encryptSupply Whether to encrypt the total supply
     */
    constructor(
        string memory _name,
        string memory _symbol,
        uint8 _decimals,
        uint256 _totalSupply,
        bool _encryptSupply
    ) {
        name = _name;
        symbol = _symbol;
        decimals = _decimals;
        owner = msg.sender;
        isSupplyEncrypted = _encryptSupply;

        if (_encryptSupply) {
            // Store encrypted total supply using euint128
            _encryptedTotalSupply = TFHE.asEuint128(_totalSupply);
            TFHE.allowThis(_encryptedTotalSupply);
        } else {
            // Store public total supply
            totalSupply = _totalSupply;
        }

        // Mint all tokens to creator using euint128
        euint128 initialBalance = TFHE.asEuint128(_totalSupply);
        _encryptedBalances[msg.sender] = initialBalance;
        TFHE.allowThis(initialBalance);
        TFHE.allow(initialBalance, msg.sender);

        emit Transfer(address(0), msg.sender);
    }

    /**
     * @notice Get encrypted balance of an account
     * @param account The address to query
     * @return Encrypted balance
     */
    function balanceOf(address account) public view returns (euint128) {
        return _encryptedBalances[account];
    }

    /**
     * @notice Transfer tokens to another address
     * @param to Recipient address
     * @param amount Encrypted amount to transfer
     */
    function transfer(address to, einput amount, bytes calldata inputProof) public returns (bool) {
        require(to != address(0), "Transfer to zero address");

        // Convert input to encrypted amount using euint128
        euint128 transferAmount = TFHE.asEuint128(amount, inputProof);

        // Check sender has enough balance
        ebool canTransfer = TFHE.le(transferAmount, _encryptedBalances[msg.sender]);
        _transfer(msg.sender, to, transferAmount, canTransfer);

        return true;
    }

    /**
     * @notice Internal transfer function
     */
    function _transfer(
        address from,
        address to,
        euint128 amount,
        ebool isTransferAllowed
    ) internal {
        // Subtract from sender (only if transfer is allowed)
        euint128 amountToSub = TFHE.select(isTransferAllowed, amount, TFHE.asEuint128(0));
        _encryptedBalances[from] = TFHE.sub(_encryptedBalances[from], amountToSub);

        // Add to recipient (only if transfer is allowed)
        euint128 amountToAdd = TFHE.select(isTransferAllowed, amount, TFHE.asEuint128(0));
        _encryptedBalances[to] = TFHE.add(_encryptedBalances[to], amountToAdd);

        // Allow both parties to view their new balances
        TFHE.allow(_encryptedBalances[from], from);
        TFHE.allow(_encryptedBalances[to], to);
        TFHE.allowThis(_encryptedBalances[from]);
        TFHE.allowThis(_encryptedBalances[to]);

        emit Transfer(from, to);
    }

    /**
     * @notice Approve spender to spend tokens
     * @param spender Address authorized to spend
     * @param amount Encrypted amount to approve
     */
    function approve(address spender, einput amount, bytes calldata inputProof) public returns (bool) {
        euint128 approvalAmount = TFHE.asEuint128(amount, inputProof);

        _encryptedAllowances[msg.sender][spender] = approvalAmount;
        TFHE.allow(approvalAmount, spender);
        TFHE.allowThis(approvalAmount);

        emit Approval(msg.sender, spender);
        return true;
    }

    /**
     * @notice Transfer tokens on behalf of another address
     * @param from Address to transfer from
     * @param to Address to transfer to
     * @param amount Encrypted amount to transfer
     */
    function transferFrom(
        address from,
        address to,
        einput amount,
        bytes calldata inputProof
    ) public returns (bool) {
        require(to != address(0), "Transfer to zero address");

        euint128 transferAmount = TFHE.asEuint128(amount, inputProof);

        // Check allowance
        ebool hasAllowance = TFHE.le(transferAmount, _encryptedAllowances[from][msg.sender]);

        // Check balance
        ebool hasBalance = TFHE.le(transferAmount, _encryptedBalances[from]);

        // Both conditions must be true
        ebool canTransfer = TFHE.and(hasAllowance, hasBalance);

        // Update allowance
        euint128 amountToDeduct = TFHE.select(canTransfer, transferAmount, TFHE.asEuint128(0));
        _encryptedAllowances[from][msg.sender] = TFHE.sub(
            _encryptedAllowances[from][msg.sender],
            amountToDeduct
        );

        // Perform transfer
        _transfer(from, to, transferAmount, canTransfer);

        return true;
    }

    /**
     * @notice Get encrypted allowance
     * @param _owner Token owner
     * @param spender Spender address
     */
    function allowance(address _owner, address spender) public view returns (euint128) {
        return _encryptedAllowances[_owner][spender];
    }

    /**
     * @notice Request decryption of total supply (owner only)
     * @return Request ID for gateway decryption
     */
    function requestTotalSupplyDecryption() public onlyOwner returns (uint256) {
        require(isSupplyEncrypted, "Supply is not encrypted");

        uint256[] memory cts = new uint256[](1);
        cts[0] = Gateway.toUint256(_encryptedTotalSupply);

        return Gateway.requestDecryption(
            cts,
            this.callbackTotalSupply.selector,
            0,
            block.timestamp + 100,
            false
        );
    }

    /**
     * @notice Callback for total supply decryption
     */
    function callbackTotalSupply(
        uint256 /*requestId*/,
        uint128 decryptedSupply
    ) public onlyGateway {
        totalSupply = decryptedSupply;
        emit TotalSupplyRevealed(decryptedSupply);
    }

    /**
     * @notice Mint new tokens (owner only, for testing)
     * @param to Address to receive tokens
     * @param amount Amount to mint
     */
    function mint(address to, uint256 amount) public onlyOwner {
        euint128 mintAmount = TFHE.asEuint128(amount);
        _encryptedBalances[to] = TFHE.add(_encryptedBalances[to], mintAmount);

        TFHE.allow(_encryptedBalances[to], to);
        TFHE.allowThis(_encryptedBalances[to]);

        if (!isSupplyEncrypted) {
            totalSupply += amount;
        } else {
            _encryptedTotalSupply = TFHE.add(_encryptedTotalSupply, mintAmount);
            TFHE.allowThis(_encryptedTotalSupply);
        }

        emit Transfer(address(0), to);
    }
}

